DROP TABLE IF EXISTS public.proposal;CREATE TABLE public.proposal (  id INTEGER NOT NULL,  "dataParaMudanca" public.datetime NULL,  "dataProposta" public.datetime NULL,  garantia VARCHAR(50) NULL,  motivacao VARCHAR(100),  "propostaAluguel" DOUBLE PRECISION NULL,  status VARCHAR(50) NULL,  "ticketID" INTEGER,  "dataAprovacao" public.datetime,  "inquilinoEnviouDocumentos" INTEGER NULL,  "dataDocumentosEnviados" public.datetime,  "proprietarioEnviouDocumentos" INTEGER NULL,  "dataDocumentosProprietarioEnviados" TIMESTAMP,  "inquilinoAceitouContrato" INTEGER NULL,  "proprietarioAceitouContrato" INTEGER NULL,  "statusDocumentacaoInq" VARCHAR(50) NULL,  "statusDocumentacaoProp" VARCHAR(50) NULL,  "fazerTermoAditivo" INTEGER NULL,  "preProposta_id" INTEGER,  "criadoEm" TIMESTAMP NULL,  "atualizadoEm" TIMESTAMP null,  "qtdeEnviosDocumentacaoInq" INTEGER NULL,  "primeiroEnvioDocInq" public.datetime)WITH (oids = false);